package com.fitbite.controller;
import com.fitbite.dto.*; import com.fitbite.entity.*; import com.fitbite.exception.ResourceNotFoundException; import com.fitbite.repository.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api") public class MetaController{private final CategoryRepository cats;private final HealthGoalRepository goals;private final IngredientRepository ingredients;public MetaController(CategoryRepository c,HealthGoalRepository g,IngredientRepository i){cats=c;goals=g;ingredients=i;}
 @GetMapping("/categories") public ApiResponse<?> categories(){return ApiResponse.ok("Categories fetched",cats.findAll());}
 @GetMapping("/health-goals") public ApiResponse<?> goals(){return ApiResponse.ok("Health goals fetched",goals.findAll());}
 @GetMapping("/ingredients") public ApiResponse<?> ingredients(@RequestParam(defaultValue="")String q){return ApiResponse.ok("Ingredients fetched",q.isBlank()?ingredients.findAll():ingredients.findTop20ByNameContainingIgnoreCaseOrderByNameAsc(q));}
 @PostMapping("/admin/categories") @PreAuthorize("hasRole('ADMIN')") public ApiResponse<?> createCategory(@RequestBody Category c){if(cats.findByNameIgnoreCase(c.getName()).isPresent())throw new IllegalArgumentException("Category already exists");return ApiResponse.ok("Category created",cats.save(Category.builder().name(c.getName()).description(c.getDescription()).build()));}
 @PutMapping("/admin/categories/{id}") @PreAuthorize("hasRole('ADMIN')") public ApiResponse<?> updateCategory(@PathVariable Long id,@RequestBody Category c){Category x=cats.findById(id).orElseThrow(()->new ResourceNotFoundException("Category not found"));x.setName(c.getName());x.setDescription(c.getDescription());return ApiResponse.ok("Category updated",cats.save(x));}
 @DeleteMapping("/admin/categories/{id}") @PreAuthorize("hasRole('ADMIN')") public ApiResponse<?> deleteCategory(@PathVariable Long id){cats.deleteById(id);return ApiResponse.ok("Category deleted",null);}
 @PostMapping("/admin/health-goals") @PreAuthorize("hasRole('ADMIN')") public ApiResponse<?> createGoal(@RequestBody HealthGoal g){return ApiResponse.ok("Health goal created",goals.save(HealthGoal.builder().name(g.getName()).description(g.getDescription()).foodsToConsider(g.getFoodsToConsider()).foodsCommonlyLimited(g.getFoodsCommonlyLimited()).build()));}
 @PutMapping("/admin/health-goals/{id}") @PreAuthorize("hasRole('ADMIN')") public ApiResponse<?> updateGoal(@PathVariable Long id,@RequestBody HealthGoal g){HealthGoal x=goals.findById(id).orElseThrow(()->new ResourceNotFoundException("Health goal not found"));x.setName(g.getName());x.setDescription(g.getDescription());x.setFoodsToConsider(g.getFoodsToConsider());x.setFoodsCommonlyLimited(g.getFoodsCommonlyLimited());return ApiResponse.ok("Health goal updated",goals.save(x));}
 @DeleteMapping("/admin/health-goals/{id}") @PreAuthorize("hasRole('ADMIN')") public ApiResponse<?> deleteGoal(@PathVariable Long id){goals.deleteById(id);return ApiResponse.ok("Health goal deleted",null);}
}
